import numpy as np
import pandas as pd
import random

def task_func(rows=3, cols=2, min_val=0, max_val=100, seed=0):
    if rows <= 0 or cols <= 0:
        return pd.DataFrame()
    if min_val > max_val:
        raise ValueError("min_val must be less than or equal to max_val")

    rng = random.Random(seed)
    matrix = [[rng.randint(min_val, max_val) for _ in range(cols)] for _ in range(rows)]
    return pd.DataFrame(matrix)
